/**
 * Errors returned across the UniFFI boundary.
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidUrl(message: String
    )
    case InvalidTheme(message: String
    )
    case InvalidInput(message: String
    )
    case Connection(message: String
    )
    case Auth(message: String
    )
    case Rpc(message: String
    )
    case Orbit(message: String, reason: FfiOrbitErrorReason
    )
    case Closed

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidUrl(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidTheme(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Connection(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Auth(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Rpc(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Orbit(
            message: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterTypeFfiOrbitErrorReason.read(from: &buf)
            )
        case 8: return .Closed

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidUrl(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidTheme(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidInput(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Connection(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Auth(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Rpc(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Orbit(message,reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            FfiConverterTypeFfiOrbitErrorReason.write(reason, into: &buf)
            
        
        case .Closed:
            writeInt(&buf, Int32(8))
        
        }
    }
}


